20	// cidPrefix prefixes every content identifier.
21	const cidPrefix = "sha256:"
22	
23	// object is a fully received object held in process memory.
24	type object struct {
25		cid    string
26		size   int
27		chunks [][]byte // raw chunk bytes, in reconstruction order
28		cids   []string // chunk identifiers, parallel to chunks
29	}
30	
31	// pin records a retention guarantee for one object. A nil expiresAt means
32	// the object is retained permanently; otherwise the pin is in force until
33	// the given instant. Pins live in process memory only and are not preserved
34	// across restarts.
35	type pin struct {
36		expiresAt *time.Time
37	}
38	
39	// validPin reports whether p is in force at now. Expired pins are
40	// equivalent to no pin at all.
41	func validPin(p pin, now time.Time) bool {
42		return p.expiresAt == nil || p.expiresAt.After(now)
43	}
44	
45	// blockRef holds one unique stored block. refs counts the live objects that
46	// reference the block; a block repeated within one object still counts once.
47	type blockRef struct {
48		data []byte
49		refs int
50	}
51	
52	// store is an in-process content-addressed object store. Objects are
53	// immutable once inserted; inserts and deletes happen under the write lock
54	// so readers never observe a partially written object. Blocks are stored
55	// once and shared by every object that references them; a block is dropped
56	// as soon as no live object references it.
57	type store struct {
58		mu       sync.RWMutex
59		objects  map[string]*object
60		blocks   map[string]*blockRef
61		pins     map[string]pin
62		metadata map[string][]metadataRevision
63		audit    *auditLog // nil until wired by the HTTP surface
64	}
65	
66	func newStore() *store {
67		return &store{
68			objects:  make(map[string]*object),
69			blocks:   make(map[string]*blockRef),
70			pins:     make(map[string]pin),
71			metadata: make(map[string][]metadataRevision),
72		}
73	}
74	
75	// chunkCID returns the identifier for one chunk's raw bytes.
76	func chunkCID(data []byte) string {
77		sum := sha256.Sum256(data)
78		return cidPrefix + hex.EncodeToString(sum[:])
79	}
80	
81	// rootCID derives the object identifier from the deterministic manifest: the
82	// total object length followed by the ordered chunk identifiers, encoded as
83	// "size:<N>\n" then one "<cid>\n" line per chunk.
84	func rootCID(size int, cids []string) string {
85		var b strings.Builder
86		fmt.Fprintf(&b, "size:%d\n", size)
87		for _, c := range cids {
88			b.WriteString(c)
89			b.WriteByte('\n')
90		}
91		sum := sha256.Sum256([]byte(b.String()))
92		return cidPrefix + hex.EncodeToString(sum[:])
93	}
94	
95	// put stores the object, or returns the existing one when the same root
96	// identifier is already present. Exactly one concurrent caller observes
97	// created == true for a given object. Newly stored objects register their
98	// unique chunks in the shared block table; repeated chunks within the
99	// object and chunks shared with other objects are stored only once. The
100	// audit event for the action is appended under the same lock, so event
101	// order matches commit order; providerID is set only for remote fetches.
102	func (s *store) put(obj *object, action string, providerID *string) (stored *object, created bool) {
103		s.mu.Lock()
104		defer s.mu.Unlock()
105		if existing, ok := s.objects[obj.cid]; ok {
106			s.audit.append(objectAuditRecord(action, existing, false, providerID))
107			return existing, false
108		}
109		s.objects[obj.cid] = obj
110		seen := make(map[string]bool, len(obj.cids))
111		for i, c := range obj.cids {
112			if b, ok := s.blocks[c]; ok {
113				obj.chunks[i] = b.data // share the stored copy
114				if !seen[c] {
115					b.refs++
116				}
117			} else {
118				s.blocks[c] = &blockRef{data: obj.chunks[i], refs: 1}
119			}
120			seen[c] = true
121		}
122		s.audit.append(objectAuditRecord(action, obj, true, providerID))
123		return obj, true
124	}
125	
126	// get returns the object for a root identifier, or nil when absent.
127	func (s *store) get(cid string) *object {
128		s.mu.RLock()
129		defer s.mu.RUnlock()
130		return s.objects[cid]
131	}
132	
133	// getBlock returns the raw bytes of a stored block, or nil when no live
134	// object references it.
135	func (s *store) getBlock(cid string) []byte {
136		s.mu.RLock()
137		defer s.mu.RUnlock()
138		if b, ok := s.blocks[cid]; ok {
139			return b.data
140		}
141		return nil
142	}
143	
144	// storageStats is a consistent snapshot of the store's occupancy.
145	type storageStats struct {
146		objects      int
147		logicalBytes int
148		blocks       int
149		storedBytes  int
150	}
151	
152	// stats snapshots object and deduplicated block occupancy under one lock
153	// hold, so the four counters always describe the same instant.
154	func (s *store) stats() storageStats {
155		s.mu.RLock()
156		defer s.mu.RUnlock()
157		st := storageStats{objects: len(s.objects), blocks: len(s.blocks)}
158		for _, obj := range s.objects {
159			st.logicalBytes += obj.size
160		}
161		for _, b := range s.blocks {
162			st.storedBytes += len(b.data)
163		}
164		return st
165	}
166	
167	// setPin pins cid with the given expiration, replacing any previous pin. It
168	// reports ok == false when the object does not exist. created is true when
169	// no valid pin was in force at now. The check and the update are atomic
170	// with respect to garbage collection.
171	func (s *store) setPin(cid string, expiresAt *time.Time, now time.Time) (created, ok bool) {
172		s.mu.Lock()
173		defer s.mu.Unlock()
174		if _, exists := s.objects[cid]; !exists {
175			return false, false
176		}
177		existing, found := s.pins[cid]
178		created = !found || !validPin(existing, now)
179		s.pins[cid] = pin{expiresAt: expiresAt}
180		result := "updated"
181		if created {
182			result = "created"
183		}
184		s.audit.append(auditRecord{action: auditPinPut, result: result, cid: strPtr(cid)})
185		return created, true
186	}
187	
188	// removePin deletes the pin for cid, reporting whether a valid pin was in
189	// force at now. Expired pins are removed lazily and reported as absent.
190	func (s *store) removePin(cid string, now time.Time) bool {
191		s.mu.Lock()
192		defer s.mu.Unlock()
193		p, found := s.pins[cid]
194		if !found || !validPin(p, now) {
195			delete(s.pins, cid)
196			return false
197		}
198		delete(s.pins, cid)
199		s.audit.append(auditRecord{action: auditPinDelete, result: "deleted", cid: strPtr(cid)})
200		return true
201	}
202	
203	// pinEntry is one live pin in a listing.
204	type pinEntry struct {
205		cid       string
206		expiresAt *time.Time
207	}
208	
209	// listPins returns the pins in force at now, sorted by cid.
210	func (s *store) listPins(now time.Time) []pinEntry {
211		s.mu.RLock()
212		defer s.mu.RUnlock()
213		entries := []pinEntry{}
214		for cid, p := range s.pins {
215			if validPin(p, now) {
216				entries = append(entries, pinEntry{cid: cid, expiresAt: p.expiresAt})
217			}
218		}
219		sort.Slice(entries, func(i, j int) bool { return entries[i].cid < entries[j].cid })
220		return entries
221	}
222	
223	// collectGarbage removes every object with no valid pin in force at now, or
224	// only counts them when dryRun is true. It returns the affected cids in
225	// lexical order and the sum of their body sizes. The sweep is atomic with
226	// respect to pin updates and object reads.
227	func (s *store) collectGarbage(now time.Time, dryRun bool) (cids []string, totalBytes int) {
228		s.mu.Lock()
229		defer s.mu.Unlock()
230		cids = []string{}
231		for cid, obj := range s.objects {
232			if p, pinned := s.pins[cid]; pinned && validPin(p, now) {
233				continue
234			}
235			cids = append(cids, cid)
236			totalBytes += obj.size
237		}
238		sort.Strings(cids)
239		if !dryRun {
240			for _, cid := range cids {
241				obj := s.objects[cid]
242				delete(s.objects, cid)
243				delete(s.metadata, cid)
244				s.releaseBlocks(obj)
245			}
246			for cid, p := range s.pins {
247				if !validPin(p, now) {
248					delete(s.pins, cid)
249				}
250			}
251		}
252		action := auditGCCollect
253		result := "collected"
254		if dryRun {
255			action = auditGCPreview
256			result = "previewed"
257		}
258		s.audit.append(auditRecord{
259			action:  action,
260			result:  result,
261			objects: intPtr(len(cids)),
262			bytes:   intPtr(totalBytes),
263		})
264		return cids, totalBytes
265	}
266	
267	// releaseBlocks drops the object's block references, removing any block no
268	// other live object uses. The caller must hold the write lock.
269	func (s *store) releaseBlocks(obj *object) {
270		seen := make(map[string]bool, len(obj.cids))
271		for _, c := range obj.cids {
272			if seen[c] {
273				continue
274			}
275			seen[c] = true
276			b, ok := s.blocks[c]
277			if !ok {
278				continue
279			}
280			b.refs--
281			if b.refs == 0 {
282				delete(s.blocks, c)
283			}
284		}
285	}
286	
287	// metadataRevision is one immutable metadata revision of an object. Each
288	// object's revisions are kept in commit order, so the revision number of
289	// entry i is i+1. Metadata lives in process memory only: it creates no pin,
290	// takes no part in storage statistics, bundles or the audit log, and is
291	// deleted atomically with its object by garbage collection.
292	type metadataRevision struct {
293		revision    int64
294		contentType *string
295		labels      map[string]string
296		updatedAt   time.Time
297	}
298	
299	// commitMetadata appends one metadata revision for cid when expected equals
300	// the current revision number (0 before the first write). The check and the
301	// append happen under the write lock, so exactly one of several concurrent
302	// writers carrying the same expected revision commits. The returned string
303	// is empty on success or the error code to report: object_not_found or
304	// revision_conflict. created is true for the first revision of an object.
305	func (s *store) commitMetadata(cid string, expected int64, contentType *string, labels map[string]string, now time.Time) (rev metadataRevision, created bool, code string) {
306		s.mu.Lock()
307		defer s.mu.Unlock()
308		if _, ok := s.objects[cid]; !ok {
309			return metadataRevision{}, false, "object_not_found"
310		}
311		history := s.metadata[cid]
312		if int64(len(history)) != expected {
313			return metadataRevision{}, false, "revision_conflict"
314		}
315		rev = metadataRevision{
316			revision:    expected + 1,
317			contentType: contentType,
318			labels:      labels,
319			updatedAt:   now.UTC(),
320		}
321		s.metadata[cid] = append(history, rev)
322		return rev, expected == 0, ""
323	}
324	
325	// metadataAt returns the current metadata revision for cid, or the requested
326	// historical revision when revision > 0. The returned string is empty on
327	// success or the error code to report: object_not_found, metadata_not_found
328	// or metadata_revision_not_found.
329	func (s *store) metadataAt(cid string, revision int64) (metadataRevision, string) {
330		s.mu.RLock()
331		defer s.mu.RUnlock()
332		if _, ok := s.objects[cid]; !ok {
333			return metadataRevision{}, "object_not_found"
334		}
335		history := s.metadata[cid]
336		if len(history) == 0 {
337			return metadataRevision{}, "metadata_not_found"
338		}
339		if revision == 0 {
340			return history[len(history)-1], ""
341		}
342		if revision > int64(len(history)) {
343			return metadataRevision{}, "metadata_revision_not_found"
344		}
345		return history[revision-1], ""
346	}
347	
348	// validCID reports whether s has the "sha256:<64 lowercase hex>" shape.
349	func validCID(s string) bool {
350		if len(s) != len(cidPrefix)+64 || !strings.HasPrefix(s, cidPrefix) {
351			return false
352		}
353		for _, c := range s[len(cidPrefix):] {
354			if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'f') {
355				return false
356			}
357		}
358		return true
359	}
