1	package server
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"io"
7		"mime"
8		"net/http"
9		"net/url"
10		"regexp"
11		"time"
12		"unicode"
13		"unicode/utf8"
14	)
15	
16	// Metadata value bounds. contentType is null or a short printable string;
17	// labels are a small string map with identifier-like keys. Lengths count
18	// Unicode code points.
19	const (
20		maxMetadataLabels         = 64
21		maxMetadataContentTypeLen = 255
22		maxMetadataLabelValueLen  = 256
23	)
24	
25	// metadataLabelKey matches the only legal label key shape.
26	var metadataLabelKey = regexp.MustCompile(`^[a-z0-9][a-z0-9._-]{0,63}$`)
27	
28	// metadataRequest is the strictly decoded PUT body. RawMessage fields stay
29	// nil for missing keys but hold the literal "null" for JSON nulls, so the
30	// two cases stay distinguishable.
31	type metadataRequest struct {
32		ExpectedRevision json.RawMessage    `json:"expectedRevision"`
33		ContentType      json.RawMessage    `json:"contentType"`
34		Labels           *map[string]string `json:"labels"`
35	}
36	
37	// metadataResponse is the JSON body of metadata reads and writes. Labels
38	// encode as an object with keys in lexical order; contentType is null when
39	// unset.
40	type metadataResponse struct {
41		CID         string            `json:"cid"`
42		Revision    int64             `json:"revision"`
43		ContentType *string           `json:"contentType"`
44		Labels      map[string]string `json:"labels"`
45		UpdatedAt   time.Time         `json:"updatedAt"`
46	}
47	
48	// metadataByID handles GET and PUT on /v1/objects/{cid}/metadata.
49	func (s *store) metadataByID(w http.ResponseWriter, r *http.Request) {
50		switch r.Method {
51		case http.MethodGet:
52			s.getMetadata(w, r)
53		case http.MethodPut:
54			s.putMetadata(w, r)
55		default:
56			w.Header().Set("Allow", "GET, PUT")
57			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
58		}
59	}
60	
61	// putMetadata handles PUT /v1/objects/{cid}/metadata.
62	func (s *store) putMetadata(w http.ResponseWriter, r *http.Request) {
63		cid := r.PathValue("cid")
64		if !validCID(cid) {
65			writeError(w, http.StatusBadRequest, "invalid_cid")
66			return
67		}
68		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
69		if err != nil || mediaType != "application/json" {
70			writeError(w, http.StatusUnsupportedMediaType, "unsupported_media_type")
71			return
72		}
73		body, err := io.ReadAll(r.Body)
74		if err != nil {
75			writeError(w, http.StatusBadRequest, "invalid_request")
76			return
77		}
78		if !wellFormedJSON(body) {
79			writeError(w, http.StatusBadRequest, "invalid_request")
80			return
81		}
82		var req metadataRequest
83		dec := json.NewDecoder(bytes.NewReader(body))
84		dec.DisallowUnknownFields()
85		if err := dec.Decode(&req); err != nil {
86			writeError(w, http.StatusBadRequest, "invalid_request")
87			return
88		}
89		if req.ExpectedRevision == nil || req.ContentType == nil || req.Labels == nil {
90			writeError(w, http.StatusBadRequest, "invalid_request")
91			return
92		}
93		expected, err := parseInt(req.ExpectedRevision)
94		if err != nil || expected < 0 {
95			writeError(w, http.StatusBadRequest, "invalid_request")
96			return
97		}
98		var contentType *string
99		if err := json.Unmarshal(req.ContentType, &contentType); err != nil {
100			writeError(w, http.StatusBadRequest, "invalid_request")
101			return
102		}
103		if contentType != nil && !validMetadataContentType(*contentType) {
104			writeError(w, http.StatusUnprocessableEntity, "invalid_metadata")
105			return
106		}
107		if !validMetadataLabels(*req.Labels) {
108			writeError(w, http.StatusUnprocessableEntity, "invalid_metadata")
109			return
110		}
111		rev, created, code := s.commitMetadata(cid, int64(expected), contentType, *req.Labels, time.Now())
112		switch code {
113		case "object_not_found":
114			writeError(w, http.StatusNotFound, code)
115			return
116		case "revision_conflict":
117			writeError(w, http.StatusConflict, code)
118			return
119		}
120		status := http.StatusOK
121		if created {
122			status = http.StatusCreated
123		}
124		writeMetadata(w, status, cid, rev)
125	}
126	
127	// getMetadata handles GET /v1/objects/{cid}/metadata. Without query
128	// parameters it returns the current revision; a single positive decimal
129	// revision parameter selects a historical revision.
130	func (s *store) getMetadata(w http.ResponseWriter, r *http.Request) {
131		cid := r.PathValue("cid")
132		if !validCID(cid) {
133			writeError(w, http.StatusBadRequest, "invalid_cid")
134			return
135		}
136		query, err := url.ParseQuery(r.URL.RawQuery)
137		if err != nil {
138			writeError(w, http.StatusBadRequest, "invalid_request")
139			return
140		}
141		var revision int64
142		for key, values := range query {
143			if key != "revision" || len(values) != 1 {
144				writeError(w, http.StatusBadRequest, "invalid_request")
145				return
146			}
147			v, ok := parseAuditInt(values[0])
148			if !ok || v < 1 {
149				writeError(w, http.StatusBadRequest, "invalid_request")
150				return
151			}
152			revision = v
153		}
154		rev, code := s.metadataAt(cid, revision)
155		if code != "" {
156			writeError(w, http.StatusNotFound, code)
157			return
158		}
159		writeMetadata(w, http.StatusOK, cid, rev)
160	}
161	
162	// writeMetadata encodes one revision; labels always encode as an object,
163	// never null.
164	func writeMetadata(w http.ResponseWriter, status int, cid string, rev metadataRevision) {
165		labels := rev.labels
166		if labels == nil {
167			labels = map[string]string{}
168		}
169		writeJSON(w, status, metadataResponse{
170			CID:         cid,
171			Revision:    rev.revision,
172			ContentType: rev.contentType,
173			Labels:      labels,
174			UpdatedAt:   rev.updatedAt,
175		})
176	}
177	
178	// validMetadataContentType reports whether s is 1 to 255 code points with no
179	// control characters.
180	func validMetadataContentType(s string) bool {
181		n := utf8.RuneCountInString(s)
182		return n >= 1 && n <= maxMetadataContentTypeLen && !hasControlChar(s)
183	}
184	
185	// validMetadataLabels reports whether the label set obeys the entry count,
186	// key shape and value bounds.
187	func validMetadataLabels(labels map[string]string) bool {
188		if len(labels) > maxMetadataLabels {
189			return false
190		}
191		for k, v := range labels {
192			if !metadataLabelKey.MatchString(k) {
193				return false
194			}
195			if utf8.RuneCountInString(v) > maxMetadataLabelValueLen || hasControlChar(v) {
196				return false
197			}
198		}
199		return true
200	}
201	
202	// hasControlChar reports whether s contains a Unicode control character.
203	func hasControlChar(s string) bool {
204		for _, r := range s {
205			if unicode.IsControl(r) {
206				return true
207			}
208		}
209		return false
210	}
