13	// null expiresAt pins permanently.
14	type pinRequest struct {
15		ExpiresAt *string `json:"expiresAt"`
16	}
17	
18	// pinResponse is the JSON body returned by pin creation, update and listing.
19	// ExpiresAt is null for permanent pins.
20	type pinResponse struct {
21		CID       string     `json:"cid"`
22		ExpiresAt *time.Time `json:"expiresAt"`
23	}
24	
25	// pinListResponse is the JSON body of GET /v1/pins.
26	type pinListResponse struct {
27		Pins []pinResponse `json:"pins"`
28	}
