38	// pinByID handles PUT and DELETE on /v1/pins/{cid}.
39	func (s *store) pinByID(w http.ResponseWriter, r *http.Request) {
40		switch r.Method {
41		case http.MethodPut:
42			s.putPin(w, r)
43		case http.MethodDelete:
44			s.deletePin(w, r)
45		default:
46			w.Header().Set("Allow", "PUT, DELETE")
47			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
48		}
49	}
50	
51	// putPin handles PUT /v1/pins/{cid}.
52	func (s *store) putPin(w http.ResponseWriter, r *http.Request) {
53		cid := r.PathValue("cid")
54		if !validCID(cid) {
55			writeError(w, http.StatusBadRequest, "invalid_cid")
56			return
57		}
58		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
59		if err != nil || mediaType != "application/json" {
60			writeError(w, http.StatusUnsupportedMediaType, "unsupported_media_type")
61			return
62		}
63		now := time.Now()
64		body, err := io.ReadAll(r.Body)
65		if err != nil {
66			writeError(w, http.StatusBadRequest, "invalid_request")
67			return
68		}
69		var req pinRequest
70		if len(bytes.TrimSpace(body)) > 0 {
71			dec := json.NewDecoder(bytes.NewReader(body))
72			dec.DisallowUnknownFields()
73			if err := dec.Decode(&req); err != nil {
74				writeError(w, http.StatusBadRequest, "invalid_request")
75				return
76			}
77			if err := dec.Decode(&struct{}{}); err != io.EOF {
78				writeError(w, http.StatusBadRequest, "invalid_request")
79				return
80			}
81		}
82		var expiresAt *time.Time
83		if req.ExpiresAt != nil {
84			t, err := time.Parse(time.RFC3339, *req.ExpiresAt)
85			if err != nil || !t.After(now) {
86				writeError(w, http.StatusUnprocessableEntity, "invalid_expiration")
87				return
88			}
89			expiresAt = &t
90		}
91		created, ok := s.setPin(cid, expiresAt, now)
92		if !ok {
93			writeError(w, http.StatusNotFound, "object_not_found")
94			return
95		}
96		status := http.StatusOK
97		if created {
98			status = http.StatusCreated
99		}
100		writeJSON(w, status, pinResponse{CID: cid, ExpiresAt: expiresAt})
101	}
102	
103	// deletePin handles DELETE /v1/pins/{cid}.
104	func (s *store) deletePin(w http.ResponseWriter, r *http.Request) {
105		cid := r.PathValue("cid")
106		if !validCID(cid) {
107			writeError(w, http.StatusBadRequest, "invalid_cid")
