47		if rec.Code != http.StatusNotFound {
48			t.Fatalf("empty metadata status = %d, want %d", rec.Code, http.StatusNotFound)
49		}
50		assertErrorCode(t, rec, "metadata_not_found")
51	
52		// First write creates revision 1.
53		rec = putMetadata(t, h, obj.CID, `{"expectedRevision":0,"contentType":"text/plain","labels":{"b":"2","a":"1"}}`, "application/json")
54		if rec.Code != http.StatusCreated {
55			t.Fatalf("create status = %d, want %d", rec.Code, http.StatusCreated)
56		}
57		first := decodeMetadataResponse(t, rec)
58		if first.CID != obj.CID || first.Revision != 1 || first.ContentType == nil || *first.ContentType != "text/plain" {
59			t.Fatalf("unexpected create response: %+v", first)
60		}
61		if len(first.Labels) != 2 || first.Labels["a"] != "1" || first.Labels["b"] != "2" {
62			t.Fatalf("unexpected labels: %+v", first.Labels)
63		}
64		if _, err := time.Parse(time.RFC3339Nano, first.UpdatedAt.UTC().Format(time.RFC3339Nano)); err != nil {
65			t.Fatalf("updatedAt not RFC3339Nano: %v", err)
66		}
67		if first.UpdatedAt.Location() != time.UTC {
68			t.Fatalf("updatedAt not UTC: %v", first.UpdatedAt)
69		}
70		// Labels encode sorted by key.
71		if body := rec.Body.String(); strings.Index(body, `"a"`) > strings.Index(body, `"b"`) {
72			t.Fatalf("labels not sorted by key: %s", body)
73		}
74	
75		// Rewriting identical content still creates a new revision.
76		rec = putMetadata(t, h, obj.CID, `{"expectedRevision":1,"contentType":"text/plain","labels":{"b":"2","a":"1"}}`, "application/json")
77		if rec.Code != http.StatusOK {
78			t.Fatalf("rewrite status = %d, want %d", rec.Code, http.StatusOK)
79		}
80		if got := decodeMetadataResponse(t, rec); got.Revision != 2 {
81			t.Fatalf("rewrite revision = %d, want 2", got.Revision)
82		}
83	
84		// A stale expected revision conflicts.
85		rec = putMetadata(t, h, obj.CID, `{"expectedRevision":1,"contentType":null,"labels":{}}`, "application/json")
86		if rec.Code != http.StatusConflict {
87			t.Fatalf("stale write status = %d, want %d", rec.Code, http.StatusConflict)
88		}
89		assertErrorCode(t, rec, "revision_conflict")
90	
91		// A changed write at the current revision succeeds.
92		rec = putMetadata(t, h, obj.CID, `{"expectedRevision":2,"contentType":null,"labels":{}}`, "application/json")
93		if rec.Code != http.StatusOK {
94			t.Fatalf("update status = %d, want %d", rec.Code, http.StatusOK)
95		}
96		third := decodeMetadataResponse(t, rec)
97		if third.Revision != 3 || third.ContentType != nil || len(third.Labels) != 0 {
98			t.Fatalf("unexpected update response: %+v", third)
99		}
100		if !strings.Contains(rec.Body.String(), `"labels":{}`) {
101			t.Fatalf("empty labels should encode as {}: %s", rec.Body.String())
102		}
103	
104		// Current revision is the latest; history stays readable.
105		got := decodeMetadataResponse(t, getMetadata(t, h, obj.CID, ""))
106		if got.Revision != 3 || got.ContentType != nil {
107			t.Fatalf("current revision = %+v, want revision 3 with null contentType", got)
108		}
109		got = decodeMetadataResponse(t, getMetadata(t, h, obj.CID, "?revision=1"))
110		if got.Revision != 1 || got.ContentType == nil || *got.ContentType != "text/plain" || got.Labels["a"] != "1" {
111			t.Fatalf("historical revision = %+v, want revision 1 content", got)
112		}
113		if !got.UpdatedAt.Equal(first.UpdatedAt) {
114			t.Fatalf("revision 1 updatedAt changed: %v vs %v", got.UpdatedAt, first.UpdatedAt)
115		}
116	
117		// A revision that does not exist.
118		rec = getMetadata(t, h, obj.CID, "?revision=4")
119		if rec.Code != http.StatusNotFound {
120			t.Fatalf("missing revision status = %d, want %d", rec.Code, http.StatusNotFound)

