	if contentType != "" {
		req.Header.Set("Content-Type", contentType)
	}
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	return rec
}

func getRef(t *testing.T, h http.Handler, name, query string) *httptest.ResponseRecorder {
